package ro.leo.visual;
import ro.leo.i18n.L;import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import org.json.*;import java.io.*;import java.util.*;
/** Own DownloadManager IDs only. Secondary-storage promotion verifies the copy before source removal. */
final class PodcastDownloads {
 static String label(String status){return "ready".equals(status)?L.t("Salvat"):"copying".equals(status)?L.t("Se copiază"):"failed".equals(status)?L.t("Eșuat"):"queued".equals(status)?L.t("Programat"):L.t("Salvare în așteptare");}
 static JSONArray jobs(Context c)throws Exception{JSONObject s=PocketStore.read(c,"podcast-jobs");return s.optJSONArray("jobs")==null?new JSONArray():s.getJSONArray("jobs");}
 static void save(Context c,JSONArray jobs)throws Exception{PocketStore.write(c,"podcast-jobs",new JSONObject().put("jobs",jobs));}
 static File primary(Context c)throws IOException{File d=c.getExternalFilesDir(android.os.Environment.DIRECTORY_PODCASTS);if(d==null||!d.isDirectory()&&!d.mkdirs())throw new IOException("Podcast staging unavailable");return d;}
 static File allowedRoot(Context c,File target)throws IOException{File root=primary(c);if(FileTransfers.inside(root,target))return root;for(File candidate:SaveLocations.folders(c).values())if(FileTransfers.inside(candidate,target))return candidate;throw new IOException("Podcast destination outside allowed storage");}
 static synchronized long enqueue(Context c,String url,String title,File destination)throws Exception{allowedRoot(c,destination);if(destination.exists()||!destination.getParentFile().isDirectory()&&!destination.getParentFile().mkdirs())throw new IOException("Podcast destination unavailable");File stage=new File(primary(c),destination.getName());if(stage.exists())throw new IOException("Podcast staging name exists");JSONArray rows=jobs(c),next=new JSONArray();for(int n=0;n<rows.length();n++){JSONObject j=rows.getJSONObject(n);if(rows.length()<100||n>0||!"ready".equals(j.optString("status")))next.put(j);}if(next.length()>=100)throw new IOException("Maximum 100 podcast jobs");DownloadManager dm=(DownloadManager)c.getSystemService(Context.DOWNLOAD_SERVICE);long id=dm.enqueue(FeedsActivity.downloadRequest(url,title,stage));try{next.put(new JSONObject().put("id",id).put("title",title).put("url",url).put("stage",stage.getPath()).put("destination",destination.getPath()).put("status","queued"));save(c,next);}catch(Exception e){dm.remove(id);throw e;}return id;}
 static synchronized JSONObject find(Context c,long id)throws Exception{JSONArray rows=jobs(c);for(int n=0;n<rows.length();n++)if(rows.getJSONObject(n).optLong("id",-1)==id)return rows.getJSONObject(n);return null;}
 static synchronized void state(Context c,long id,String status,String error)throws Exception{JSONArray rows=jobs(c);for(int n=0;n<rows.length();n++){JSONObject j=rows.getJSONObject(n);if(j.optLong("id",-1)==id){j.put("status",status).put("error",error);save(c,rows);return;}}}
 static synchronized void forget(Context c,long id)throws Exception{JSONArray rows=jobs(c),next=new JSONArray();for(int n=0;n<rows.length();n++)if(rows.getJSONObject(n).optLong("id",-1)!=id)next.put(rows.get(n));save(c,next);}
 static void request(Context c,long id){c.startForegroundService(new Intent(c,PodcastTransferService.class).putExtra("id",id));}
 static void reconcile(Context c){try{JSONArray rows=jobs(c);DownloadManager dm=(DownloadManager)c.getSystemService(Context.DOWNLOAD_SERVICE);for(int n=0;n<rows.length();n++){JSONObject j=rows.getJSONObject(n);long id=j.getLong("id");if("ready".equals(j.optString("status"))){if(!j.optString("stage").equals(j.optString("destination"))&&new File(j.optString("stage")).isFile())request(c,id);continue;}try(Cursor cursor=dm.query(new DownloadManager.Query().setFilterById(id))){if(cursor!=null&&cursor.moveToFirst()){int status=cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(status==DownloadManager.STATUS_SUCCESSFUL||status==DownloadManager.STATUS_FAILED)request(c,id);}}}}catch(Exception ignored){}}
 static void finish(Context c,long id)throws Exception{JSONObject j=find(c,id);if(j==null)return;DownloadManager dm=(DownloadManager)c.getSystemService(Context.DOWNLOAD_SERVICE);File source=new File(j.getString("stage")),destination=new File(j.getString("destination"));if(!FileTransfers.inside(primary(c),source)||!source.getName().equals(destination.getName()))throw new IOException("Invalid podcast staging record");boolean already="ready".equals(j.optString("status"));if(already){if(!source.getCanonicalFile().equals(destination.getCanonicalFile()))dm.remove(id);return;}int status=0,reason=0;String local="";try(Cursor cursor=dm.query(new DownloadManager.Query().setFilterById(id))){if(cursor!=null&&cursor.moveToFirst()){status=cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));reason=cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_REASON));local=cursor.getString(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_LOCAL_URI));}}if(status==DownloadManager.STATUS_FAILED){state(c,id,"failed","DownloadManager "+reason);return;}if(status!=DownloadManager.STATUS_SUCCESSFUL)return;if(local==null||!"file".equals(Uri.parse(local).getScheme())||!new File(Uri.parse(local).getPath()).getCanonicalFile().equals(source.getCanonicalFile()))throw new IOException("Download record does not match owned staging file");if(!source.isFile()||source.length()>512L*1024*1024||java.nio.file.Files.isSymbolicLink(source.toPath()))throw new IOException("Podcast staging invalid or over 512 MiB");try{File root=allowedRoot(c,destination);if(!source.getCanonicalFile().equals(destination.getCanonicalFile())){File parent=destination.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("Destination card unavailable");state(c,id,"copying","");if(destination.exists()){if(!destination.isFile()||destination.length()!=source.length()||!FileTransfers.digest(destination).equals(FileTransfers.digest(source)))throw new IOException("Destination collision; no file overwritten");}else FileTransfers.transfer(primary(c),source,root,parent,false);state(c,id,"ready","");dm.remove(id);}else state(c,id,"ready","");}catch(Exception e){state(c,id,"waiting",e.getMessage()==null?"Storage error":e.getMessage());throw e;}}
}
